create table public.terra_admins(user_id uuid primary key references auth.users(id));
alter table public.terra_admins enable row level security;
create policy terra_admin_self on public.terra_admins for select to authenticated using (user_id=(select auth.uid()));
grant select on public.terra_admins to authenticated;
create table public.terra_properties(id uuid primary key default gen_random_uuid(), title text not null check(length(title) between 3 and 140), category text not null check(category in ('Fazenda','Sítio','Chácara','Terreno','Casa')), mode text not null default 'Comprar' check(mode in ('Comprar','Arrendar','Parceria')), city text not null, state text not null, price numeric not null default 0 check(price>=0), area numeric not null default 0 check(area>=0), unit text not null default 'ha' check(unit in ('ha','m²')), description text not null default '', photos jsonb not null default '[]' check(jsonb_typeof(photos)='array'), whatsapp text not null default '', published boolean not null default true, created_at timestamptz not null default now());
alter table public.terra_properties enable row level security;
create policy terra_read on public.terra_properties for select to anon,authenticated using(published or exists(select 1 from public.terra_admins where user_id=(select auth.uid())));
create policy terra_manage on public.terra_properties for all to authenticated using(exists(select 1 from public.terra_admins where user_id=(select auth.uid()))) with check(exists(select 1 from public.terra_admins where user_id=(select auth.uid())));
grant select on public.terra_properties to anon,authenticated;
grant insert,update,delete on public.terra_properties to authenticated;
create table public.terra_settings(id int primary key check(id=1), whatsapp text not null default '', brand text not null default 'TERRA NOBRE');
insert into public.terra_settings(id) values(1);
alter table public.terra_settings enable row level security;
create policy terra_settings_read on public.terra_settings for select to anon,authenticated using(true);
create policy terra_settings_manage on public.terra_settings for update to authenticated using(exists(select 1 from public.terra_admins where user_id=(select auth.uid()))) with check(exists(select 1 from public.terra_admins where user_id=(select auth.uid())));
grant select on public.terra_settings to anon,authenticated; grant update on public.terra_settings to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('terra-nobre','terra-nobre',true,5242880,array['image/jpeg','image/png','image/webp']);
create policy terra_images_insert on storage.objects for insert to authenticated with check(bucket_id='terra-nobre' and exists(select 1 from public.terra_admins where user_id=(select auth.uid())));
create policy terra_images_delete on storage.objects for delete to authenticated using(bucket_id='terra-nobre' and exists(select 1 from public.terra_admins where user_id=(select auth.uid())));
